css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); border-radius: 50%; background: linear-gradient(to bottom, var(--accent-2) 50%, var(--accent) 50%); position: relative; animation: taichi calc(var(--loader-speed) * 1.8) linear infinite; }
.loader::before, .loader::after { content: ''; position: absolute; left: 25%; width: 50%; height: 50%; border-radius: 50%; box-sizing: border-box; }
.loader::before { top: 0; background: var(--accent); }
.loader::after { top: 50%; background: var(--accent-2); }
@keyframes taichi { to { transform: rotate(360deg); } }
